package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Adds a plan for the person: an amount of 0.00 or more with up to two decimals, a start date (blank: the sheet's
 * today), every N days (a whole number, at least 1) or
 * monthly on a day of the month (1 to 31), and an end date not before the start.
 */
public class AddPlan {
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    private static final Pattern EVERY = Pattern.compile("\\d{1,9}");
    private static final Pattern DAY = Pattern.compile("\\d{1,2}");

    public void add(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @RequestBody PlanRequest request, Plans plans, SheetClock clock, Audit audit) throws InvalidPlanException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String start = request == null || request.start() == null ? "" : request.start().trim();
        String every = request == null || request.every() == null ? "" : request.every().trim();
        String day = request == null || request.day() == null ? "" : request.day().trim();
        String end = request == null || request.end() == null ? "" : request.end().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidPlanException("The amount must be 0.00 or more with up to two decimals");
        }
        Integer monthDay = null;
        if (!day.isEmpty()) {
            if (!every.isEmpty()) {
                throw new InvalidPlanException("A plan runs either every N days or monthly on a day, not both");
            }
            if (!DAY.matcher(day).matches() || Integer.parseInt(day) < 1 || Integer.parseInt(day) > 31) {
                throw new InvalidPlanException("The day of the month must be a whole number from 1 to 31");
            }
            monthDay = Integer.parseInt(day);
        } else if (!EVERY.matcher(every).matches() || Integer.parseInt(every) < 1) {
            throw new InvalidPlanException("Every must be a whole number of days, at least 1");
        }
        LocalDate from;
        LocalDate to;
        try {
            from = start.isEmpty() ? clock.today(sheet) : LocalDate.parse(start);
            to = LocalDate.parse(end);
        } catch (DateTimeParseException e) {
            throw new InvalidPlanException("A plan needs a valid start and end date");
        }
        if (to.isBefore(from)) {
            throw new InvalidPlanException("A plan may not end before it starts");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        int days = monthDay == null ? Integer.parseInt(every) : 0;
        plans.add(sheet, person.id(), value, from, days, monthDay, to);
        audit.record("PLAN_ADDED sheet=" + sheet + " by=" + user + " name=" + person.name() + " amount="
                + value.toPlainString() + " start=" + from
                + (monthDay == null ? " every=" + days : " day=" + monthDay) + " end=" + to);
    }
}
package net.officefloor.hq.app.plan;

/** Body of POST /api/sheets/{sheet}/people/{person}/plans. */
public record PlanRequest(String amount, String start, String every, String end, String day) {
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: an amount (two decimals), from {@code start} every {@code every} days (or, when {@code day} is set,
 *  monthly on that day of the month) to {@code end} (ISO dates),
 *  with how many claims it has {@code generated} so far, and its {@code nextDates}: the first five plan dates after
 *  the sheet's today and on or before the end, leaving out the dates it was paused for; and whether it is
 *  {@code paused} now (paused and not yet resumed); and its amount {@code changes}, oldest first, each as
 *  {@code <date> amount=<amount>}. {@code amount} is the current one: the amount of the claims it generates next. */
public record Plan(long id, long person, String amount, String start, int every, String end, int generated, Integer day,
        List<String> nextDates, boolean paused, List<String> changes) {

    /** A pause: from the day paused up to, not including, the day resumed (null: still paused). */
    record Pause(LocalDate from, LocalDate until) {
        boolean covers(LocalDate d) {
            return !d.isBefore(from) && (until == null || d.isBefore(until));
        }
    }

    /** How many dates {@code nextDates} shows at most. */
    static final int NEXT = 5;

    /** The plan's dates after {@code after} (none left out when null) and up to {@code last}, at most {@code limit}:
     *  the start then every N days, or, for a monthly plan, its day in every month from the start's month (on the
     *  month's last day when shorter), leaving out any before the start and any a pause covers. */
    static List<LocalDate> dates(LocalDate start, int every, Integer day, List<Pause> pauses, LocalDate after,
            LocalDate last, int limit) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate d = start; !d.isAfter(last) && dates.size() < limit; d = d.plusDays(every)) {
                if ((after == null || d.isAfter(after)) && !paused(pauses, d)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last) && dates.size() < limit;
                month = month.plusMonths(1)) {
            LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!d.isBefore(start) && !d.isAfter(last) && (after == null || d.isAfter(after))
                    && !paused(pauses, d)) {
                dates.add(d);
            }
        }
        return dates;
    }

    private static boolean paused(List<Pause> pauses, LocalDate d) {
        return pauses.stream().anyMatch(p -> p.covers(d));
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * For every plan on the sheet, in the order added, adds a DRAFT claim of the plan's amount, dated that day with an
 * empty note, for each plan date (the start, then every N days; or a monthly plan's day in each month) up to the end and the sheet's today that has none
 * yet and no pause skips, as the claim form's BuildClaim adds one. A date the form would refuse (due inside a closed period, or after the
 * person's retirement) is skipped, and tried again next time. A viewer's generate makes none.
 */
public class GeneratePlans {
    public void generate(@PathVariable("sheet") String sheet, @RequestParam("user") String user, Plans plans,
            People people, Claims claims, Periods periods, Settings settings, Holidays holidays, SheetClock clock,
            ClaimLog log, Audit audit, Rollup rollup, Roles roles, ObjectResponse<GeneratedPlans> response) {
        LocalDate today = clock.today(sheet);
        int made = 0;
        boolean viewer = Role.VIEWER.equals(roles.of(sheet, user));
        for (Plan plan : viewer ? List.<Plan>of() : plans.list(sheet)) {
            Person person = people.find(sheet, plan.person());
            if (person == null) {
                continue;
            }
            LocalDate end = LocalDate.parse(plan.end());
            LocalDate last = end.isBefore(today) ? end : today;
            for (LocalDate day : plans.dates(plan, last)) {
                if (plans.made(plan.id(), day)) {
                    continue;
                }
                LocalDate dueBy = person.dueBy(sheet, day, today, settings, holidays);
                if (periods.closedOn(sheet, dueBy) || person.retiredBefore(day)) {
                    continue;
                }
                ClaimInput input = new ClaimInput(new BigDecimal(plan.amount()), day, "");
                Rollup.Snapshot before = rollup.take(sheet);
                long id = claims.add(sheet, person.id(), input, dueBy, person.termsOn(sheet, today, settings));
                log.record(sheet, user, id);
                plans.recordMade(plan.id(), day, id);
                audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.addedAuditFields(person.name()));
                if (periods.softClosedOn(sheet, dueBy)) {
                    claims.setLateEntry(sheet, id);
                    audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
                }
                rollup.record(sheet, user, before);
                made++;
            }
        }
        response.send(new GeneratedPlans(made, claims.list(sheet), plans.list(sheet)));
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The plans of the people on a sheet, and the plan dates each has made a claim for. */
@Repository
public class Plans {

    private RowMapper<Plan> row(LocalDate today) {
        return (rs, i) -> {
            List<Plan.Pause> pauses = pauses(rs.getLong("id"));
            LocalDate start = rs.getDate("start_date").toLocalDate();
            LocalDate end = rs.getDate("end_date").toLocalDate();
            int every = rs.getInt("every_days");
            Integer day = (Integer) rs.getObject("month_day");
            List<String> next = Plan.dates(start, every, day, pauses, today, end, Plan.NEXT).stream()
                    .map(LocalDate::toString).toList();
            return new Plan(rs.getLong("id"), rs.getLong("person_id"),
                    rs.getBigDecimal("amount").setScale(2).toPlainString(), start.toString(), every, end.toString(),
                    rs.getInt("generated"), day, next,
                    pauses.stream().anyMatch(p -> p.until() == null), changes(rs.getLong("id")));
        };
    }

    private final JdbcTemplate jdbc;

    private final SheetClock clock;

    public Plans(JdbcTemplate jdbc, SheetClock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    private static final String SELECT = "SELECT p.id, p.person_id, p.amount, p.start_date, p.every_days, p.end_date,"
            + " p.month_day, (SELECT COUNT(*) FROM plan_claim c WHERE c.plan_id = p.id) AS generated FROM plan p";

    /** Every plan on the sheet, in the order added, with its next dates after the sheet's today. */
    public List<Plan> list(String sheet) {
        return jdbc.query(SELECT + " WHERE p.sheet = ? ORDER BY p.id", row(clock.today(sheet)), sheet);
    }

    /** The sheet's plan with this id, or null. */
    public Plan find(String sheet, long id) {
        return jdbc.query(SELECT + " WHERE p.sheet = ? AND p.id = ?", row(clock.today(sheet)), sheet, id).stream()
                .findFirst().orElse(null);
    }

    /** The plan's dates up to {@code last}, leaving out those its pauses skip. */
    public List<LocalDate> dates(Plan plan, LocalDate last) {
        return Plan.dates(LocalDate.parse(plan.start()), plan.every(), plan.day(), pauses(plan.id()), null, last,
                Integer.MAX_VALUE);
    }

    private List<Plan.Pause> pauses(long plan) {
        return jdbc.query("SELECT paused_on, resumed_on FROM plan_pause WHERE plan_id = ? ORDER BY id",
                (rs, i) -> new Plan.Pause(rs.getDate("paused_on").toLocalDate(),
                        rs.getDate("resumed_on") == null ? null : rs.getDate("resumed_on").toLocalDate()), plan);
    }

    private List<String> changes(long plan) {
        return jdbc.query("SELECT changed_on, amount FROM plan_change WHERE plan_id = ? ORDER BY id",
                (rs, i) -> rs.getDate("changed_on").toLocalDate() + " amount="
                        + rs.getBigDecimal("amount").setScale(2).toPlainString(), plan);
    }

    /** Changes the plan's amount on {@code day}, for the claims it generates from then on. */
    public void changeAmount(long plan, LocalDate day, BigDecimal amount) {
        jdbc.update("UPDATE plan SET amount = ? WHERE id = ?", amount, plan);
        jdbc.update("INSERT INTO plan_change (plan_id, changed_on, amount) VALUES (?, ?, ?)", plan, Date.valueOf(day),
                amount);
    }

    /** Pauses the plan from {@code day}: false, changing nothing, when it is already paused. */
    public boolean pause(long plan, LocalDate day) {
        return jdbc.update("INSERT INTO plan_pause (plan_id, paused_on) SELECT ?, ? FROM DUAL WHERE NOT EXISTS"
                + " (SELECT 1 FROM plan_pause WHERE plan_id = ? AND resumed_on IS NULL)", plan, Date.valueOf(day), plan) > 0;
    }

    /** Resumes the paused plan from {@code day}: false, changing nothing, when it is not paused. */
    public boolean resume(long plan, LocalDate day) {
